from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        trie = {'#': 0}

        def add(word, delta):
            node = trie
            for ch in word:
                if ch not in node:
                    node[ch] = {'#': 0}
                node = node[ch]
                node['#'] += delta

        def query(node, depth):
            best = depth
            for ch, child in node.items():
                if ch != '#' and child['#'] >= k:
                    best = max(best, query(child, depth + 1))
            return best

        n = len(words)
        for word in words:
            add(word, 1)

        answer = []
        for i in range(n):
            if n - 1 < k:
                answer.append(0)
                continue
            add(words[i], -1)
            answer.append(query(trie, 0))
            add(words[i], 1)

        return answer
